<x-app-layout>
    <style>
@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');

  .shooting-range-zone-guide{
    --bg: #000000;
    --bg-alt: #0A0A0A;
    --panel: #141414;
    --line: #262626;
    --brass: #FF3131;
    --brass-bright: #FF5C5C;
    --range: #8A8A8A;
    --paper: #FFFFFF;
    --paper-muted: #A6A6A6;
    --target-red: #FF3131;
  }

  *{ box-sizing: border-box; margin:0; padding:0; }
  .shooting-range-zone-guide{ scroll-behavior: smooth; }
  .shooting-range-zone-guide{
    background: var(--bg);
    color: var(--paper);
    font-family: 'Inter', sans-serif;
    overflow-x: hidden;
  }
  .shooting-range-zone-guide ::selection{ background: var(--brass); color: #000000; }
  .shooting-range-zone-guide h1, .shooting-range-zone-guide h2, .shooting-range-zone-guide h3, .shooting-range-zone-guide .eyebrow, .shooting-range-zone-guide .tag, .shooting-range-zone-guide .num{
    font-family: 'Manrope', sans-serif;
    text-transform: uppercase;
  }

  .mono{ font-family: 'JetBrains Mono', monospace; }

  /* ---------- SLIDES ---------- */
  .shooting-range-zone-guide .slide{
    min-height: 100vh;
    width: 100%;
    scroll-snap-align: start;
    display: flex;
    align-items: center;
    padding: 6vh 8vw;
    position: relative;
    border-bottom: 1px solid var(--line);
  }
  .shooting-range-zone-guide .slide:nth-of-type(odd){ background: var(--bg); }
  .shooting-range-zone-guide .slide:nth-of-type(even){ background: var(--bg-alt); }

  .shooting-range-zone-guide .slide-inner{
    max-width: 1200px;
    margin: 0 auto;
    width: 100%;
    display: grid;
    grid-template-columns: 1.1fr 0.9fr;
    gap: 5vw;
    align-items: center;
  }
  .shooting-range-zone-guide .slide-inner.reverse{ grid-template-columns: 0.9fr 1.1fr; }
  .shooting-range-zone-guide .slide-inner.reverse .visual{ order: 2; }
  .shooting-range-zone-guide .slide-inner.reverse .text{ order: 1; }
  .shooting-range-zone-guide .slide-inner.centered{
    grid-template-columns: 1fr;
    text-align: center;
    justify-items: center;
  }

  .shooting-range-zone-guide .num{
    font-size: 0.85rem;
    letter-spacing: 0.25em;
    color: var(--brass);
    margin-bottom: 1.2rem;
    display: flex;
    align-items: center;
    gap: 0.8rem;
  }
  .shooting-range-zone-guide .num .ring{
    width: 10px; height: 10px;
    border: 2px solid var(--brass);
    border-radius: 50%;
  }

  .shooting-range-zone-guide .eyebrow{
    font-size: 0.8rem;
    letter-spacing: 0.2em;
    color: var(--paper-muted);
    margin-bottom: 0.6rem;
  }
  .shooting-range-zone-guide h2{
    font-size: clamp(1.8rem, 3.4vw, 2.9rem);
    font-weight: 600;
    line-height: 1.15;
    margin-bottom: 1.1rem;
    color: var(--paper);
  }
  .shooting-range-zone-guide p.desc{
    font-size: 1.08rem;
    line-height: 1.65;
    color: var(--paper-muted);
    max-width: 46ch;
  }
  .shooting-range-zone-guide .centered p.desc{ max-width: 60ch; }

  .shooting-range-zone-guide .tag{
    display: inline-block;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    color: var(--brass-bright);
    border: 1px solid var(--brass);
    border-radius: 3px;
    padding: 0.25rem 0.6rem;
    margin-top: 1.4rem;
  }
  .shooting-range-zone-guide .tag.red{ color: #FF9B9B; border-color: var(--target-red); }
  .shooting-range-zone-guide .tag.green{ color: #D9D9D9; border-color: var(--range); }

  .shooting-range-zone-guide ul.points{ margin-top: 1.2rem; list-style: none; }
  .shooting-range-zone-guide ul.points li{
    position: relative;
    padding-left: 1.4rem;
    margin-bottom: 0.55rem;
    color: var(--paper-muted);
    font-size: 1rem;
    line-height: 1.5;
  }
  .shooting-range-zone-guide ul.points li::before{
    content: "";
    position: absolute;
    left: 0; top: 0.55em;
    width: 6px; height: 6px;
    background: var(--brass);
    border-radius: 50%;
  }

  /* ---------- VISUALS ---------- */
  .shooting-range-zone-guide .visual{
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .shooting-range-zone-guide .frame{
    width: 100%;
    max-width: 420px;
    aspect-ratio: 4/3;
    background: var(--panel);
    border: 1px solid var(--line);
    border-radius: 10px;
    position: relative;
    overflow: hidden;
    box-shadow: 0 30px 60px -20px rgba(0,0,0,0.55);
  }
  .shooting-range-zone-guide .frame svg{ width: 100%; height: 100%; }

  /* ---------- HERO ---------- */
  .shooting-range-zone-guide .hero{
    background: radial-gradient(ellipse at 50% 40%, #0D0D0D 0%, #000000 70%);
  }
  .shooting-range-zone-guide .hero .slide-inner{ grid-template-columns: 1fr; text-align:center; justify-items:center; }
  .shooting-range-zone-guide .brand-logo{ height: 34px; width: auto; margin-bottom: 2.4rem; opacity: 0.95; }
  .shooting-range-zone-guide .hero .brand-logo{ height: 102px; margin-bottom: 2.8rem; }
  .shooting-range-zone-guide .closing .brand-logo{ height: 60px; margin-bottom: 1.8rem; }
  .hero-rings{ width: min(60vw, 340px); height: min(60vw, 340px); margin-bottom: 2.2rem; }
  .hero-rings circle{ fill: none; stroke: var(--brass); opacity: 0.9; }
  .hero-rings circle.c1{ opacity: 1; }
  .hero-rings circle.c4{ stroke: var(--brass-bright); }
  .hero-rings .dot{ fill: var(--brass-bright); }
  @media (prefers-reduced-motion: no-preference){
    .hero-rings .pulse{ animation: shooting-range-zone-pulse 3.2s ease-in-out infinite; transform-origin: center; }
  }
  @keyframes shooting-range-zone-pulse{
    0%,100%{ opacity: 0.35; }
    50%{ opacity: 0.85; }
  }
  .shooting-range-zone-guide .hero h1{
    font-size: clamp(2.2rem, 6vw, 4.4rem);
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: 0.01em;
  }
  .shooting-range-zone-guide .hero .brand{ color: var(--brass-bright); }
  .shooting-range-zone-guide .hero p.desc{ margin: 1.4rem auto 0; max-width: 56ch; text-align:center; font-size: 1.15rem; }
  .shooting-range-zone-guide .scroll-hint{
    margin-top: 3rem;
    font-size: 0.78rem;
    letter-spacing: 0.2em;
    color: var(--paper-muted);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
  }
  .shooting-range-zone-guide .scroll-hint .arrow{ font-size: 1.1rem; color: var(--brass); }
  @media (prefers-reduced-motion: no-preference){
    .shooting-range-zone-guide .scroll-hint .arrow{ animation: shooting-range-zone-bob 1.8s ease-in-out infinite; }
  }
  @keyframes shooting-range-zone-bob{ 0%,100%{ transform: translateY(0);} 50%{ transform: translateY(6px);} }

  /* ---------- CLOSING ---------- */
  .shooting-range-zone-guide .closing{ background: linear-gradient(180deg, var(--bg-alt) 0%, #000000 100%); }
  .shooting-range-zone-guide .closing h2{ font-size: clamp(2rem, 4vw, 3.2rem); }
  .shooting-range-zone-guide .closing .cta{
    margin-top: 2rem;
    display: inline-flex;
    align-items: center;
    gap: 0.7rem;
    background: var(--brass);
    color: #000000;
    font-family: 'Manrope', sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    font-size: 0.95rem;
    padding: 0.9rem 1.8rem;
    border-radius: 4px;
  }

  /* ---------- SIDE NAV ---------- */
  .shooting-range-zone-guide .side-nav{
    position: fixed;
    right: 26px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    flex-direction: column;
    gap: 10px;
    z-index: 50;
  }
  .shooting-range-zone-guide .side-nav button{
    width: 12px; height: 12px;
    border-radius: 50%;
    border: 2px solid var(--paper-muted);
    background: transparent;
    cursor: pointer;
    padding: 0;
    transition: border-color 0.25s, background 0.25s, transform 0.25s;
  }
  .shooting-range-zone-guide .side-nav button.active{
    border-color: var(--brass-bright);
    background: var(--brass-bright);
    transform: scale(1.25);
  }
  .shooting-range-zone-guide .side-nav button:hover{ border-color: var(--brass-bright); }

  .shooting-range-zone-guide .progress-count{
    position: fixed;
    right: 26px;
    bottom: 22px;
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.75rem;
    color: var(--paper-muted);
    z-index: 50;
  }
  .shooting-range-zone-guide .progress-count .cur{ color: var(--brass-bright); }


  .shooting-range-zone-guide .shot-frame{
    width: 100%;
    max-width: 560px;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid var(--line);
    box-shadow: 0 30px 60px -20px rgba(0,0,0,0.55);
    background: var(--panel);
  }
  .shooting-range-zone-guide .shot-frame img{ width: 100%; height: auto; display: block; }
  .shooting-range-zone-guide .hero-logo-big{ width: min(70vw, 460px); height: auto; margin-bottom: 2.2rem; }

  .shooting-range-zone-guide .slide-inner.stacked{
    grid-template-columns: 1fr;
    justify-items: center;
    max-width: 760px;
  }
  .shooting-range-zone-guide .slide-inner.stacked .visual{ margin-top: 2.6rem; width: 100%; justify-content: center; }
  .shooting-range-zone-guide .slide-inner.stacked .text{ width: 100%; }

  @media (max-width: 860px){
    .shooting-range-zone-guide .slide-inner, .shooting-range-zone-guide .slide-inner.reverse{
      grid-template-columns: 1fr;
      text-align: left;
    }
    .shooting-range-zone-guide .slide-inner.reverse .visual{ order: 1; }
    .shooting-range-zone-guide .slide-inner.reverse .text{ order: 2; }
    .shooting-range-zone-guide .slide{ padding: 8vh 7vw; }
    .shooting-range-zone-guide .side-nav{ display: none; }
    .shooting-range-zone-guide .progress-count{ left: 7vw; right: auto; }
  }
    </style>

    <div class="shooting-range-zone-guide">
<nav class="side-nav" id="sideNav"></nav>
