    </div>

<script>
    (() => {
        const root = document.querySelector('.shooting-range-zone-guide');

        if (!root) {
            return;
        }

        const slides = Array.from(root.querySelectorAll('.slide'));
        const nav = root.querySelector('#sideNav');
        const curNum = root.querySelector('#curNum');
        const totalNum = root.querySelector('#totalNum');

        if (!nav || !curNum || !totalNum || slides.length === 0) {
            return;
        }

        nav.innerHTML = '';
        totalNum.textContent = String(slides.length).padStart(2, '0');

        slides.forEach((slide, index) => {
            const button = document.createElement('button');
            button.setAttribute('aria-label', slide.dataset.title || `Slajd ${index + 1}`);
            button.addEventListener('click', () => slide.scrollIntoView({ behavior: 'smooth' }));
            nav.appendChild(button);
        });

        const dots = Array.from(nav.children);
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (!entry.isIntersecting) {
                    return;
                }

                const index = slides.indexOf(entry.target);
                dots.forEach(dot => dot.classList.remove('active'));
                dots[index]?.classList.add('active');
                curNum.textContent = String(index + 1).padStart(2, '0');
            });
        }, { threshold: 0.5 });

        slides.forEach(slide => observer.observe(slide));
    })();
</script>
</x-app-layout>
